draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // family
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 20);
  ctx.lineTo(W/2 + 50, H/2 + 20);
  ctx.stroke();

  // dog
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 100 + 20 * Math.sin(t), 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 130 + 20 * Math.sin(t));
  ctx.lineTo(W/2, H/2 + 160 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 140 + 20 * Math.sin(t));
  ctx.lineTo(W/2 - 20, H/2 + 120 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 140 + 20 * Math.sin(t));
  ctx.lineTo(W/2 + 20, H/2 + 120 + 20 * Math.sin(t));
  ctx.stroke();

  // protective pose
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 20);
  ctx.lineTo(W/2 - 70 + 20 * Math.cos(t), H/2 + 100 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 20);
  ctx.lineTo(W/2 + 70 - 20 * Math.cos(t), H/2 + 100 + 20 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
